 function drawMini(){mx.clearRect(0,0,276,276);mx.fillStyle='#397ba1';mx.fillRect(0,0,276,276);for(let x=0;x<N;x+=2)for(let z=0;z<N;z+=2){let t=map[x][z];mx.fillStyle=t.biome==='water'?'#397ba1':t.biome==='sand'?'#d8c17b':t.biome==='mountain'?'#898f8a':'#70a34c';mx.fillRect(x*4.3,z*4.3,5,5)}mx.fillStyle='#fff';for(let c of creatures){mx.beginPath();mx.arc(c.x*4.3,c.z*4.3,1.7,0,7);mx.fill()}let corners=[[0,0],[W,0],[W,H],[0,H]].map(v=>worldPos(v[0],v[1]));mx.beginPath();corners.forEach((v,i)=>i?mx.lineTo(v.x*4.3,v.z*4.3):mx.moveTo(v.x*4.3,v.z*4.3));mx.closePath();mx.strokeStyle='#fff';mx.lineWidth=2;mx.stroke()}mini.addEventListener('pointerdown',e=>{let r=mini.getBoundingClientRect(),x=Math.max(0,Math.min(N-1,((e.clientX-r.left)/r.width)*N)),z=Math.max(0,Math.min(N-1,((e.clientY-r.top)/r.height)*N));camera.x=-(x-z)*TS*.95*camera.zoom;camera.y=-(x+z-N)*TS*.48*camera.zoom});
 function hint(s){let h=document.getElementById('hint');h.textContent=s;h.classList.add('show');clearTimeout(h.t);h.t=setTimeout(()=>h.classList.remove('show'),1200)}
 let drag=null,lastInfo=null;function inspectAt(p){if(p.x<0||p.z<0||p.x>=N||p.z>=N)return;let t=map[p.x][p.z],near=creatures.find(v=>Math.abs(v.x-p.x)<1.2&&Math.abs(v.z-p.z)<1.2),panel=document.getElementById('panel');panel.classList.add('show');panel.innerHTML=near?`<h3>${near.name} — ${near.kind==='human'?'Human':'Sheep'}</h3><div class="trait"><span>Health</span><b>${Math.round(near.health)}%</b></div><div class="bar"><i style="width:${near.health}%"></i></div><div class="trait"><span>Hunger</span><b>${Math.round(near.hunger||0)}%</b></div><div class="bar"><i style="width:${near.hunger||0}%;background:#e2a84e"></i></div><div class="trait"><span>Age</span><b>${Math.floor(near.age)}</b></div><div class="trait"><span>Biome</span><b>${t.biome}</b></div>`:`<h3>${t.biome.toUpperCase()} TILE</h3><div class="trait"><span>Elevation</span><b>${t.h}</b></div><div class="trait"><span>Life</span><b>${t.tree?'Forest':t.house?'House':t.fire?'Burning':'Natural'}</b></div><div class="bar"><i style="width:${Math.max(5,(t.h+2)*11)}%"></i></div>`;clearTimeout(lastInfo);lastInfo=setTimeout(()=>panel.classList.remove('show'),4000)}
 c.addEventListener('pointerdown',e=>{c.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};if(tool!=='inspect'){let p=worldPos(e.clientX,e.clientY);applyTool(p.x,p.z);lastPaint=p.x+','+p.z}});c.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(e.clientX-drag.startX)+Math.abs(e.clientY-drag.startY)>4)drag.moved=true;if(tool==='inspect'){camera.x+=dx;camera.y+=dy}else{let p=worldPos(e.clientX,e.clientY),key=p.x+','+p.z;if(key!==lastPaint){applyTool(p.x,p.z);lastPaint=key}}drag.x=e.clientX;drag.y=e.clientY});c.addEventListener('pointerup',e=>{if(drag&&!drag.moved&&tool==='inspect')inspectAt(worldPos(e.clientX,e.clientY));drag=null;lastPaint=''});c.addEventListener('pointercancel',()=>{drag=null;lastPaint=''});
